            </div>
            <button type="submit" class="th-popup-btn th-popup-btn--destructive auth-submit-btn">Create Account</button>
          </form>

          <!-- Social Login Form -->
          <div id="formSocial" class="d-none tc">
            <p class="fs-09 c-muted mb-16">
