              pattern="[\\d ]{13,19}" placeholder="4123 4567 8901 2345"
              enterkeyhint="next" required>
          </div>
          <div class="grid-2col">
            <div class="form-group">
              <label class="form-label" for="simExpiry">Expiry Date <span aria-hidden="true">*</span></label>
