            <div class="form-group">
              <label class="form-label" for="simCvv">Security Code (CVV) <span aria-hidden="true">*</span></label>
              <span id="cvvHint" class="field-hint">3 or 4 digits</span>
              <input type="text" id="simCvv" name="cc-csc" class="form-control"
                autocomplete="cc-csc" aria-describedby="cvvHint" inputmode="numeric"
                maxlength="4" pattern="[0-9]{3,4}" placeholder="123"
                enterkeyhint="next" required>
            </div>
          </div>
          <div class="form-group mb-0">
            <label class="form-label" for="simCardHolder">Cardholder Name <span aria-hidden="true">*</span></label>
            <input type="text" id="simCardHolder" name="cc-name" class="form-control"
              autocomplete="cc-name" maxlength="80" pattern="[\\p{L} \\-\\.]+"
              placeholder="Full Name on Card" value="${escapeHtml(defaultHolder)}"
              enterkeyhint="done" required>
          </div>
        </div>
      `;
    } else {
      const defaultPhone = bookingData && bookingData.userPhone ? bookingData.userPhone : '';
      paymentSimulatorContainer.innerHTML = `
        <div class="tc">
          <h3 class="fs-11 mb-8 ${cfg.headingClass}">${escapeHtml(cfg.label)} Gateway</h3>
          <p class="fs-085 c-muted mb-16">${escapeHtml(cfg.subtitle)}</p>
          <div class="form-group max-w-280 mx-auto mb-16 tl">
            <label class="form-label" for="simGatewayPhone">${escapeHtml(cfg.inputLabel)} <span aria-hidden="true">*</span></label>
            <input type="tel" id="simGatewayPhone" name="tel" class="form-control"
              autocomplete="tel" inputmode="numeric" pattern="[\\d \\-]{9,15}"
              placeholder="${escapeHtml(cfg.placeholder)}" value="${escapeHtml(defaultPhone)}"
              enterkeyhint="done" required>
          </div>
          <div class="fs-08 ${cfg.statusBgClass} p-8-12 r-8">
            <i class="fa-solid fa-circle-check mr-4" aria-hidden="true"></i> ${escapeHtml(cfg.statusText)}
          </div>
        </div>
      `;
    }

    attachGatewayFieldListeners();
  }

  function collectAndValidatePaymentDetails() {
    const cfg = METHOD_CONFIG[selectedMethod] || METHOD_CONFIG.PROMPTPAY;
    const fields = Array.from(paymentSimulatorContainer.querySelectorAll('input'));

    for (const field of fields) {
      if (!field.checkValidity()) {
        field.setAttribute('aria-invalid', 'true');
        field.reportValidity();
        field.focus();
        return null;
      }
      field.removeAttribute('aria-invalid');
    }

    if (cfg.type === 'card') {
      const cardNumber = document.getElementById('simCardNumber').value.trim();
      const expiry = document.getElementById('simExpiry').value.trim();
      const cvv = document.getElementById('simCvv').value.trim();
      const cardHolder = document.getElementById('simCardHolder').value.trim();
      return { cardNumber, expiry, cvv, cardHolder };
    }

    if (cfg.type === 'mobile') {
      const phone = document.getElementById('simGatewayPhone').value.trim();
      return { phone };
    }

    return {};
  }

  function renderPaymentResult({ success, payment, tickets, message }) {
    if (paymentStatusIconEl) {
      paymentStatusIconEl.className = `payment-status-icon ${success ? 'payment-status-icon--success' : 'payment-status-icon--error'}`;
      paymentStatusIconEl.innerHTML = success
        ? '<i class="fa-solid fa-circle-check" aria-hidden="true"></i>'
        : '<i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i>';
    }

    if (paymentStatusTitleEl) {
      paymentStatusTitleEl.textContent = success ? 'Payment Successful' : 'Payment Failed';
    }

    if (paymentStatusMessageEl) {
      paymentStatusMessageEl.textContent = message;
    }

    if (paymentStatusDetailsEl) {
      if (success && payment) {
        const cfg = METHOD_CONFIG[payment.method] || { label: payment.method };
        const ticketList = Array.isArray(tickets) && tickets.length > 0
          ? tickets.map((t) => `${escapeHtml(t.seatNumber)} (${escapeHtml(t.ticketCode)})`).join(', ')
          : '-';
        paymentStatusDetailsEl.innerHTML = `
          <div class="payment-status-row"><span>Payment Reference</span><strong class="mono">${escapeHtml(payment.referenceCode)}</strong></div>
          <div class="payment-status-row"><span>Payment Method</span><strong>${escapeHtml(cfg.label)}</strong></div>
          <div class="payment-status-row"><span>Amount Paid</span><strong class="c-blue">${Number(payment.amount).toLocaleString()} THB</strong></div>
          <div class="payment-status-row"><span>Issued Tickets</span><strong>${ticketList}</strong></div>
        `;
        paymentStatusDetailsEl.classList.remove('d-none');
        paymentStatusDetailsEl.hidden = false;
      } else {
        paymentStatusDetailsEl.innerHTML = '';
        paymentStatusDetailsEl.classList.add('d-none');
        paymentStatusDetailsEl.hidden = true;
      }
    }

    if (paymentSuccessActionsEl) {
      paymentSuccessActionsEl.classList.toggle('d-none', !success);
      paymentSuccessActionsEl.hidden = !success;
      const viewTicketsLink = paymentSuccessActionsEl.querySelector('a[href^="/my-tickets"]');
      if (viewTicketsLink && bookingId) {
        viewTicketsLink.href = `/my-tickets?bookingId=${encodeURIComponent(bookingId)}`;
      }
    }
    if (paymentErrorActionsEl) {
      paymentErrorActionsEl.classList.toggle('d-none', success);
      paymentErrorActionsEl.hidden = success;
    }
  }

  async function submitPayment(simulateFailure = false) {
    const holderNames = validateTicketHolderInputs();
    if (!holderNames) {
      goToStep(1);
      return;
    }

    let gatewayDetails = {};
    if (!simulateFailure) {
      gatewayDetails = collectAndValidatePaymentDetails();
      if (!gatewayDetails) return;
    } else {
      gatewayDetails = { simulateFailure: true };
    }

    if (confirmPaymentBtn) {
      confirmPaymentBtn.disabled = true;
      confirmPaymentBtn.textContent = 'Processing Payment...';
    }
    if (simulateFailBtn) {
      simulateFailBtn.disabled = true;
    }

    try {
      const payload = {
        paymentMethod: selectedMethod,
        ticketHolderNames: holderNames,
        paymentDetails: {
          ...gatewayDetails,
          simulatedTimestamp: new Date().toISOString(),
          channel: 'WEB_SIMULATOR'
        }
      };

      const res = await API.booking.pay(bookingId, payload);
      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }
      if (countdownBoxEl) {
        countdownBoxEl.classList.add('d-none');
        countdownBoxEl.hidden = true;
      }

      renderPaymentResult({
        success: true,
        payment: res.payment,
        tickets: res.tickets,
        message: 'Your booking is confirmed and your electronic QR tickets have been issued.'
      });
      goToStep(4);
    } catch (err) {
      renderPaymentResult({
        success: false,
        message: err.message || 'Payment could not be processed. Please review your payment details and try again.'
      });
      goToStep(4);
    } finally {
      if (confirmPaymentBtn) {
        confirmPaymentBtn.disabled = false;
        updateGatewayHeader();
      }
      if (simulateFailBtn) {
        simulateFailBtn.disabled = false;
      }
    }
  }

  if (gatewayPaymentForm) {
    gatewayPaymentForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      await submitPayment(false);
    });
  }

  if (simulateFailBtn) {
    simulateFailBtn.addEventListener('click', async () => {
      await submitPayment(true);
    });
  }

  if (retryGatewayBtn) {
    retryGatewayBtn.addEventListener('click', () => {
      goToStep(3);
    });
  }

  if (changeMethodFromErrorBtn) {
    changeMethodFromErrorBtn.addEventListener('click', () => {
      goToStep(2);
    });
  }

  await loadBookingSummary();
});

/**
 * Shared event card rendering and bookmark handler for Home and All Events pages.
 */
(() => {
  const DEFAULT_CARD_IMG = 'https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=800&q=80';

  function esc(val) {
    return window.escapeHtml ? window.escapeHtml(val) : String(val ?? '');
  }

  function safeImg(url, fallback = DEFAULT_CARD_IMG) {
    return window.sanitizeUrl ? window.sanitizeUrl(url, fallback) : esc(url || fallback);
  }

  function heartMarkup(isBookmarked) {
    return isBookmarked
      ? '<i class="fa-solid fa-heart c-red"></i>'
      : '<i class="fa-regular fa-heart"></i>';
  }

  function formatVenue(e) {
    return e.province ? `${e.venue || ''}, ${e.province}` : (e.venue || '');
  }

  const SHORT_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function formatShortDate(dateStr) {
    if (!dateStr) return 'TBD';
    const match = String(dateStr).match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (!match) return dateStr;
    const [, year, month, day] = match;
    const monthName = SHORT_MONTHS[Number(month) - 1];
    return monthName ? `${Number(day)} ${monthName} ${year}` : dateStr;
  }

  function getMinPrice(e) {
    if (!Array.isArray(e.zones) || e.zones.length === 0) return 0;
    const prices = e.zones.map((z) => Number(z.price)).filter((p) => Number.isFinite(p));
    return prices.length ? Math.min(...prices) : 0;
  }

  function renderHomeCard(e, { cardClass, btnClass, ctaText, img, round, eventUrl }) {
    const venueText = formatVenue(e) || 'TBA';
    const dateText = formatShortDate(round.date);

    return `
      <article class="${cardClass} card-home">
        <img class="card-home-img" src="${img}" alt="${esc(e.title)}" loading="lazy">
        <button type="button" class="btn-icon card-bookmark-btn" data-bookmark-id="${esc(e.id)}"
          title="Bookmark event" aria-label="Bookmark ${esc(e.title)}">
          ${heartMarkup(Boolean(e.isBookmarked))}
        </button>
        <div class="card-home-overlay">
          <div class="card-home-info">
            <h3 class="card-home-title"><a href="${eventUrl}" class="card-link">${esc(e.title)}</a></h3>
            <div class="card-home-meta">
              <i class="fa-solid fa-location-dot" aria-hidden="true"></i>
              <span>${esc(venueText)} &bull; ${esc(dateText)}</span>
            </div>
          </div>
          <a href="${eventUrl}" class="${btnClass} card-home-cta">${esc(ctaText)}</a>
        </div>
      </article>
    `;
  }

  function renderCard(e, opts = {}) {
    const isSoon = opts.variant === 'soon' || e.status !== 'On Sale';
    const cardClass = opts.cardClass || (isSoon ? 'card-soon' : 'card-popular');
    const badgeClass = opts.badgeClass || (isSoon ? 'badge-pill-blue' : 'badge-pill-red');
    const btnClass = opts.btnClass || (isSoon ? 'btn-pill-blue' : 'btn-pill-red');
    const badgeText = opts.badgeText || (isSoon ? (e.status || 'Coming Soon') : (e.category || 'Concert'));
    const priceLabel = opts.priceLabel || (e.status === 'Coming Soon' ? 'Expected from' : 'Starts from');
    const ctaText = opts.ctaText || (e.status === 'On Sale' ? 'Buy Now' : (e.status === 'Coming Soon' ? 'Details' : e.status || 'View'));
    const round = (e.rounds && e.rounds[0]) || {};
    const img = safeImg(opts.preferPoster ? (e.posterUrl || e.galleryUrl) : (e.galleryUrl || e.posterUrl));
    const minPrice = getMinPrice(e);
    const eventUrl = `/event?id=${encodeURIComponent(e.id || '')}`;

    if (opts.layout === 'home') {
      return renderHomeCard(e, { cardClass, btnClass, ctaText, img, round, eventUrl });
    }

    return `
      <div class="${cardClass}">
        <div class="card-image-wrap">
          <span class="card-badge-floating ${badgeClass}">${esc(badgeText)}</span>
          <button type="button" class="btn-icon card-bookmark-btn" data-bookmark-id="${esc(e.id)}"
            title="Bookmark event" aria-label="Bookmark ${esc(e.title)}">
            ${heartMarkup(Boolean(e.isBookmarked))}
          </button>
          <img src="${img}" alt="${esc(e.title)}" loading="lazy">
        </div>
        <div class="card-body">
          <div class="card-subtitle">${esc(e.artist || 'Special Performance')}${opts.showCategorySubtitle ? ` • ${esc(e.category || 'Event')}` : ''}</div>
          <h3 class="card-title">${esc(e.title)}</h3>
          <div class="card-meta">
            <span><i class="fa-solid fa-location-dot c-blue mr-4"></i> ${esc(formatVenue(e))}</span>
            <span>•</span>
            <span><i class="fa-solid fa-calendar-days mr-4"></i> ${esc(round.date || 'TBD')}</span>
          </div>
          <div class="card-footer">
            <div class="card-price">
              <small>${esc(priceLabel)}</small><br>
              ${minPrice.toLocaleString()} THB
            </div>
            <a href="${eventUrl}" class="${btnClass}">${esc(ctaText)}</a>
          </div>
        </div>
      </div>
    `;
  }

  async function toggleBookmark(eventId, btn) {
    if (!Auth.isLoggedIn()) {
      Auth.openAuthModal();
      return;
    }
    try {
      const res = await API.events.toggleBookmark(eventId);
      btn.innerHTML = heartMarkup(Boolean(res.isBookmarked));
    } catch (err) {
      await Popup.alert(err.message, { title: 'Bookmark Error' });
    }
  }

  function bindBookmarkButtons(root = document) {
    root.querySelectorAll('[data-bookmark-id]').forEach((btn) => {
      btn.addEventListener('click', (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        toggleBookmark(btn.dataset.bookmarkId, btn);
      });
    });
  }

  function populateSelectOptions(events, categories, { categoryEl, provinceEl } = {}) {
    if (categoryEl) {
      const names = new Set([
        ...(categories || []).map((c) => c.name),
        ...(events || []).map((e) => e.category)
      ].filter((n) => typeof n === 'string' && n.trim()));
      const prev = categoryEl.value;
      categoryEl.innerHTML = '<option value="">All Categories</option>' +
        Array.from(names).sort((a, b) => a.localeCompare(b))
          .map((name) => `<option value="${esc(name)}">${esc(name)}</option>`)
          .join('');
      categoryEl.value = prev;
    }

    if (provinceEl) {
      const provinces = Array.from(new Set((events || []).map((e) => (e.province || '').trim()).filter(Boolean)))
        .sort((a, b) => a.localeCompare(b));
      const prev = provinceEl.value;
      provinceEl.innerHTML = '<option value="">All Provinces</option>' +
        provinces.map((p) => `<option value="${esc(p)}">${esc(p)}</option>`).join('');
      provinceEl.value = prev;
    }
  }

  window.EventCard = {
    renderCard,
    bindBookmarkButtons,
    populateSelectOptions,
    toggleBookmark,
    heartMarkup,
    safeImg,
    esc
  };
})();

/**
 * TicketHub - Event Detail Page Controller (public/js/event.js)
 * Loads event details (poster, title, artist, description, rounds, gate/show times,
 * venue, zone pricing, seating plan preview) and handles bookmarking and booking CTA.
 */

document.addEventListener('DOMContentLoaded', async () => {
  const urlParams = new URLSearchParams(window.location.search);
  const eventId = urlParams.get('id') || 'evt-1';

  const eventMetaBadgesEl = document.getElementById('eventMetaBadges');
  const eventTitleEl = document.getElementById('eventTitle');
  const eventArtistEl = document.getElementById('eventArtist');
  const eventVenueEl = document.getElementById('eventVenue');
  const eventPhoto1El = document.getElementById('eventPhoto1');
  const eventPhoto2El = document.getElementById('eventPhoto2');
  const eventDescEl = document.getElementById('eventDesc');
  const roundsListEl = document.getElementById('roundsList');
  const zonesPricingListEl = document.getElementById('zonesPricingList');
  const seatPreviewEl = document.getElementById('seatPreviewContainer');
  const bookmarkBtn = document.getElementById('bookmarkBtn');
  const infoDatesEl = document.getElementById('infoDates');
  const infoScheduleEl = document.getElementById('infoSchedule');
  const infoPriceRangeEl = document.getElementById('infoPriceRange');
  const infoOrganizerEl = document.getElementById('infoOrganizer');
  const buyNowBtn = document.getElementById('buyNowBtn');

  function esc(val) {
    return window.escapeHtml ? window.escapeHtml(val) : String(val ?? '');
  }

  function safeImg(url, fallback) {
    return window.sanitizeUrl ? window.sanitizeUrl(url, fallback) : esc(url || fallback);
  }

  function renderBookmarkLabel(isBookmarked) {
    return isBookmarked
      ? '<i class="fa-solid fa-heart c-red"></i> Bookmarked'
      : '<i class="fa-regular fa-heart"></i> Add to Bookmarks';
  }

  function renderZonesPricing(event) {
    if (!zonesPricingListEl) return;
    const zones = Array.isArray(event.zones) ? event.zones : [];
    const firstRoundZones = (event.rounds && event.rounds[0] && event.rounds[0].zones) || [];
    const availByZoneId = new Map(firstRoundZones.map((z) => [z.zoneId, z]));

    if (zones.length === 0) {
      zonesPricingListEl.innerHTML = '<p class="c-muted">Pricing information will be announced soon.</p>';
      return;
    }

    zonesPricingListEl.innerHTML = zones
      .map((z) => {
        const stats = availByZoneId.get(z.id);
        const seatMeta = stats
          ? `${stats.availableSeats}/${stats.totalSeats} seats available`
          : `${(z.rows || 4) * (z.cols || 8)} seats`;
        const priceNum = Number(z.price || 0);
        return `
          <div class="zone-price-row">
            <div>
              <strong>${esc(z.name)}</strong>
              <div class="fs-085 c-muted">${esc(seatMeta)}</div>
            </div>
            <span class="badge-pill-blue fs-085">${priceNum.toLocaleString()} THB</span>
          </div>
        `;
      })
      .join('');
  }

  async function renderSeatPreview(event) {
    if (!seatPreviewEl) return;
    const firstRound = event.rounds && event.rounds[0];
    if (!firstRound) {
      seatPreviewEl.innerHTML = '<p class="c-muted m-0">Seating plan will be available once show rounds are announced.</p>';
      return;
    }

    try {
      const seatRes = await API.booking.getSeats(event.id, firstRound.id);
      const seats = (seatRes && seatRes.seats) || [];
      if (seats.length === 0) {
        seatPreviewEl.innerHTML = '<p class="c-muted m-0">No seating chart configured yet.</p>';
        return;
      }

      const byZone = new Map();
      for (const s of seats) {
        const key = s.zoneName || s.zoneId || 'Zone';
        if (!byZone.has(key)) byZone.set(key, []);
        byZone.get(key).push(s);
      }

      const groupsHtml = Array.from(byZone.entries())
        .map(([zoneName, zoneSeats]) => {
          const previewLimit = 32;
          const visible = zoneSeats.slice(0, previewLimit);
          const extra = zoneSeats.length > previewLimit ? `<span class="fs-08 c-muted">+${zoneSeats.length - previewLimit} more</span>` : '';
          const dots = visible
            .map((s) => {
              const cls = s.status === 'AVAILABLE' ? 'available' : 'booked';
              return `<span class="seat seat-mini ${cls}" title="${esc(s.seatNumber)} (${esc(s.status)})">${esc(s.seatNumber)}</span>`;
            })
            .join('');
          return `
            <div class="event-seat-zone-group">
              <div class="fw-7 fs-09 c-ink">${esc(zoneName)}</div>
              <div class="event-seat-grid">${dots}${extra}</div>
            </div>
          `;
        })
        .join('');

      seatPreviewEl.innerHTML = `
        <div class="stage-banner mb-16">STAGE</div>
        ${groupsHtml}
        <div class="seat-legend mt-16">
          <div class="legend-item"><span class="seat seat-mini available">A1</span> Available</div>
          <div class="legend-item"><span class="seat seat-mini booked"></span> Booked / Held</div>
        </div>
      `;
    } catch (_) {
      seatPreviewEl.innerHTML = '<p class="c-muted m-0">Select Buy Now to view the interactive seating plan.</p>';
    }
  }

  function renderEvent(event) {
    document.title = `${event.title} - TicketHub`;
    if (eventTitleEl) eventTitleEl.textContent = event.title;

    if (eventMetaBadgesEl) {
      const statusBadgeCls = event.status === 'On Sale' ? 'badge-pill-red' : 'badge-pill-blue';
      eventMetaBadgesEl.innerHTML = `
        <span class="badge-pill-outline fs-08">${esc(event.category || 'Event')}</span>
        <span class="${statusBadgeCls} fs-08">${esc(event.status || 'On Sale')}</span>
      `;
    }

    if (eventArtistEl) {
      eventArtistEl.textContent = event.artist ? `Artist / Speaker: ${event.artist}` : '';
    }

    const venueFull = event.province ? `${event.venue}, ${event.province}` : (event.venue || '');
    if (eventVenueEl) {
      eventVenueEl.innerHTML = `<i class="fa-solid fa-location-dot c-blue mr-4"></i> ${esc(venueFull)}`;
    }

    const defaultImg1 = 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&w=1000&q=80';
    const defaultImg2 = 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=1000&q=80';

    if (eventPhoto1El) eventPhoto1El.src = safeImg(event.posterUrl, defaultImg1);
    if (eventPhoto2El) eventPhoto2El.src = safeImg(event.galleryUrl, defaultImg2);
    if (eventDescEl) eventDescEl.textContent = event.description || 'Join us for this exciting live event experience.';

    if (bookmarkBtn) {
      bookmarkBtn.innerHTML = renderBookmarkLabel(Boolean(event.isBookmarked));
      bookmarkBtn.onclick = async () => {
        if (!Auth.isLoggedIn()) {
          Auth.openAuthModal();
          return;
        }
        try {
          const bRes = await API.events.toggleBookmark(event.id);
          bookmarkBtn.innerHTML = renderBookmarkLabel(Boolean(bRes.isBookmarked));
        } catch (bErr) {
          await Popup.alert(bErr.message, { title: 'Bookmark Error' });
        }
      };
    }

    if (roundsListEl && event.rounds) {
      roundsListEl.innerHTML = event.rounds
        .map(
          (r) => `
            <div class="event-round-card">
              <div>
                <strong>${esc(r.label || 'Round')}</strong>
                <div class="fs-085 c-muted">
                  <i class="fa-solid fa-calendar-days mr-4"></i> ${esc(r.date)} &nbsp;
                  <i class="fa-solid fa-clock mr-4"></i> ${esc(r.time)}
                </div>
              </div>
              <span class="badge-pill-blue fs-08">${esc(event.status || 'Available')}</span>
            </div>
          `
        )
        .join('');
    }

    renderZonesPricing(event);

    const dates = (event.rounds || []).map((r) => r.date).filter(Boolean);
    if (infoDatesEl) infoDatesEl.textContent = dates.length > 0 ? dates.join(', ') : 'TBD';

    const gateTime = event.gateOpenTime || '16:00';
    const showTime = event.showTime || '19:00';
    if (infoScheduleEl) {
      infoScheduleEl.innerHTML = `
        <div>Open gate: ${esc(gateTime)}</div>
        <div>Showtime: ${esc(showTime)}</div>
      `;
    }

    if (infoPriceRangeEl) {
      const prices = (event.zones || []).map((z) => Number(z.price)).filter((p) => Number.isFinite(p));
      if (prices.length === 0) {
        infoPriceRangeEl.textContent = 'TBD';
      } else {
        const min = Math.min(...prices);
        const max = Math.max(...prices);
        infoPriceRangeEl.textContent = min === max
          ? `${min.toLocaleString()} THB`
          : `${min.toLocaleString()} - ${max.toLocaleString()} THB`;
      }
    }

    if (infoOrganizerEl) infoOrganizerEl.textContent = event.organizer || 'TicketHub Organizer';

    if (buyNowBtn) {
      if (event.status === 'Coming Soon') {
        buyNowBtn.disabled = true;
        buyNowBtn.textContent = 'Coming Soon';
        buyNowBtn.className = 'btn-pill-blue fs-115 w-100';
      } else if (event.status === 'Sold Out') {
        buyNowBtn.disabled = true;
        buyNowBtn.textContent = 'Sold Out';
        buyNowBtn.className = 'btn-pill-secondary fs-115 w-100';
      } else if (!event.isSaleOpen || event.status !== 'On Sale') {
        buyNowBtn.disabled = true;
        buyNowBtn.textContent = event.status === 'Closed' ? 'Closed' : 'Sales Closed';
        buyNowBtn.className = 'btn-pill-secondary fs-115 w-100';
      } else {
        buyNowBtn.disabled = false;
        buyNowBtn.textContent = 'Buy Now';
        buyNowBtn.className = 'btn-pill-red fs-115 w-100';
        buyNowBtn.onclick = () => {
          window.location.href = `/booking?eventId=${encodeURIComponent(event.id)}`;
        };
      }
    }
  }

  try {
    const res = await API.events.getById(eventId);
    const currentEvent = res.event;
    renderEvent(currentEvent);
    await renderSeatPreview(currentEvent);
  } catch (err) {
    console.error('Failed to load event:', err);
    if (eventTitleEl) eventTitleEl.textContent = 'Event Not Found';
    if (eventDescEl) eventDescEl.textContent = 'The requested event could not be found or has been removed.';
    if (seatPreviewEl) seatPreviewEl.innerHTML = '<p class="c-muted m-0">Unavailable</p>';
    if (buyNowBtn) {
      buyNowBtn.disabled = true;
      buyNowBtn.textContent = 'Event Unavailable';
    }
  }
});

/**
 * TicketHub - All Events Listing Controller (/event)
 * Displays all events with search, category, status, date, province, active-sale filter, sort, and bookmarking.
 */
document.addEventListener('DOMContentLoaded', async () => {
  const grid = document.getElementById('allEventsGrid');
  const countBadge = document.getElementById('eventsResultCount');
  const searchInput = document.getElementById('searchInput');
  const categoryFilter = document.getElementById('categoryFilter');
  const statusFilter = document.getElementById('statusFilter');
  const provinceFilter = document.getElementById('provinceFilter');
  const dateFilter = document.getElementById('dateFilter');
  const saleActiveFilter = document.getElementById('saleActiveFilter');
  const sortFilter = document.getElementById('sortFilter');
  const resetFilters = document.getElementById('resetFilters');
  const navSearchTrigger = document.getElementById('navSearchTrigger');

  let requestSeq = 0;
  let searchTimer = null;

  function buildFilterParams() {
    return {
      search: searchInput ? searchInput.value.trim() : '',
      category: categoryFilter ? categoryFilter.value : '',
      status: statusFilter ? statusFilter.value : '',
      province: provinceFilter ? provinceFilter.value : '',
      date: dateFilter ? dateFilter.value : '',
      saleActive: saleActiveFilter && saleActiveFilter.checked ? 'true' : '',
      sort: sortFilter ? sortFilter.value : ''
    };
  }

  function renderEvents(events) {
    if (!grid) return;
    if (countBadge) {
      countBadge.textContent = `${events.length} Event${events.length === 1 ? '' : 's'}`;
    }

    if (events.length === 0) {
      grid.innerHTML = '<p class="empty-events-msg">No events match your search or filter criteria.</p>';
      return;
    }

    grid.innerHTML = events
      .map((e) =>
        EventCard.renderCard(e, {
          variant: e.status === 'On Sale' ? 'popular' : 'soon',
          badgeText: `${e.category || 'Event'} • ${e.status || 'On Sale'}`,
          showCategorySubtitle: true,
          preferPoster: true
        })
      )
      .join('');

    EventCard.bindBookmarkButtons(grid);
  }

  async function fetchAndRender() {
    const seq = ++requestSeq;
    try {
      const res = await API.events.list(buildFilterParams());
      if (seq !== requestSeq) return;
      renderEvents((res && res.events) || []);
    } catch (err) {
      if (seq !== requestSeq) return;
      console.error('Failed to load events:', err);
      if (countBadge) countBadge.textContent = '0 Events';
      if (grid) grid.innerHTML = '<p class="empty-events-msg">Unable to load events. Please try again.</p>';
    }
  }

  try {
    const [eventsRes, categoriesRes] = await Promise.all([
      API.events.list(),
      API.categories.list()
    ]);
    const allEvents = (eventsRes && eventsRes.events) || [];
    const categories = (categoriesRes && categoriesRes.categories) || [];
    EventCard.populateSelectOptions(allEvents, categories, {
      categoryEl: categoryFilter,
      provinceEl: provinceFilter
    });

    const params = new URLSearchParams(window.location.search);
    if (searchInput && params.get('search')) searchInput.value = params.get('search');
    if (categoryFilter && params.get('category')) categoryFilter.value = params.get('category');
    if (statusFilter && params.get('status')) statusFilter.value = params.get('status');

    if (params.toString()) {
      await fetchAndRender();
    } else {
      renderEvents(allEvents);
    }
  } catch (err) {
    console.error('Failed to initialize all events page:', err);
    if (grid) grid.innerHTML = '<p class="empty-events-msg">Unable to load events. Please try again.</p>';
  }

  if (searchInput) {
    searchInput.addEventListener('input', () => {
      clearTimeout(searchTimer);
      searchTimer = setTimeout(fetchAndRender, 250);
    });
  }

  [categoryFilter, statusFilter, provinceFilter, dateFilter, saleActiveFilter, sortFilter].forEach((el) => {
    if (el) el.addEventListener('change', fetchAndRender);
  });

  if (resetFilters) {
    resetFilters.addEventListener('click', () => {
      if (searchInput) searchInput.value = '';
      [categoryFilter, statusFilter, provinceFilter, dateFilter, sortFilter].forEach((el) => {
        if (el) el.value = '';
      });
      if (saleActiveFilter) saleActiveFilter.checked = false;
      fetchAndRender();
    });
  }

  if (navSearchTrigger && searchInput) {
    navSearchTrigger.addEventListener('click', () => {
      searchInput.focus();
      searchInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
  }
});

/**
 * TicketHub - Home Page Controller (public/js/index.js)
 * Loads featured hero, popular events carousel, and upcoming/other events carousel,
 * and manages search, filtering, and sorting.
 */

document.addEventListener('DOMContentLoaded', async () => {
  const heroBanner = document.getElementById('heroBanner');
  const heroBgImg = document.getElementById('heroBgImg');
  const popularContainer = document.getElementById('popularContainer');
  const soonContainer = document.getElementById('soonContainer');
  const searchInput = document.getElementById('searchInput');
  const categoryFilter = document.getElementById('categoryFilter');
  const statusFilter = document.getElementById('statusFilter');
  const provinceFilter = document.getElementById('provinceFilter');
  const monthFilter = document.getElementById('monthFilter');
  const sortFilter = document.getElementById('sortFilter');
  const resetFilters = document.getElementById('resetFilters');

  const MONTH_NAMES = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];
  const DEFAULT_HERO_BG = 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=1920&q=80';

  let requestSeq = 0;
  let searchTimer = null;

  function populateFilterOptions(events, categories) {
    EventCard.populateSelectOptions(events, categories, {
      categoryEl: categoryFilter,
      provinceEl: provinceFilter
    });

    if (monthFilter) {
      const months = new Set();
      events.forEach((e) => (e.rounds || []).forEach((r) => {
        if (r && /^\d{4}-\d{2}/.test(r.date || '')) months.add(r.date.slice(0, 7));
      }));
      monthFilter.innerHTML =
        '<option value="">Any Month</option>' +
        Array.from(months).sort().map((ym) => {
          const [y, m] = ym.split('-');
          return `<option value="${EventCard.esc(ym)}">${MONTH_NAMES[Number(m) - 1]} ${EventCard.esc(y)}</option>`;
        }).join('');
    }
  }

  function buildFilterParams() {
    return {
      search: (searchInput.value || '').trim(),
      category: categoryFilter.value,
      status: statusFilter.value,
      province: provinceFilter ? provinceFilter.value : '',
      month: monthFilter ? monthFilter.value : '',
      sort: sortFilter ? sortFilter.value : ''
    };
  }

  function renderFeaturedHero(events) {
    if (!heroBanner) return;
    const featured = events.find((e) => e.isFeatured) || events[0];
    if (!featured) return;

    const round = (featured.rounds && featured.rounds[0]) || {};
    const dateStr = round.date ? `${round.date} • ${round.time || ''}` : 'Upcoming 2026';
    const bgImage = EventCard.safeImg(featured.posterUrl, DEFAULT_HERO_BG);

    if (heroBgImg) heroBgImg.src = bgImage;

    heroBanner.innerHTML = `
      <div class="hero-top">
        <span class="badge-pill-red">Feature Event</span>
        <button type="button" class="btn-icon hero-bookmark-btn" data-bookmark-id="${EventCard.esc(featured.id)}"
          title="Bookmark event" aria-label="Bookmark ${EventCard.esc(featured.title)}">
          ${EventCard.heartMarkup(Boolean(featured.isBookmarked))}
        </button>
      </div>
      <div class="hero-content">
        <h1 class="hero-title">${EventCard.esc(featured.title)}</h1>
        <p class="hero-desc">${EventCard.esc((featured.description || '').slice(0, 150))}...</p>
        <div class="hero-meta">
          <span><i class="fa-solid fa-location-dot c-blue mr-4"></i> ${EventCard.esc(featured.venue || 'Bangkok Arena')}</span>
          <span>•</span>
          <span><i class="fa-solid fa-calendar-days mr-4"></i> ${EventCard.esc(dateStr)}</span>
        </div>
      </div>
      <div class="hero-bottom">
        <a href="/event?id=${encodeURIComponent(featured.id)}" class="btn-pill-red fs-11 p-12-32">
          Buy Now
        </a>
      </div>
    `;

    EventCard.bindBookmarkButtons(heroBanner);
  }

  function renderCarouselSection(container, events, emptyMsg, cardOptions) {
    if (!container) return;
    if (events.length === 0) {
      container.innerHTML = `<p class="empty-events-msg">${EventCard.esc(emptyMsg)}</p>`;
      return;
    }

    container.innerHTML = events.map((e) => EventCard.renderCard(e, cardOptions(e))).join('');
    EventCard.bindBookmarkButtons(container);
  }

  async function filterAndRenderEvents() {
    const seq = ++requestSeq;
    try {
      const res = await API.events.list(buildFilterParams());
      if (seq !== requestSeq) return;
      const events = (res && res.events) || [];

      const popular = events.filter((e) => e.status === 'On Sale' || e.isFeatured);
      const soon = events.filter((e) => e.status !== 'On Sale');

      renderCarouselSection(popularContainer, popular, 'No popular events match your search criteria.', (e) => ({
        layout: 'home',
        variant: 'popular',
        ctaText: e.status === 'On Sale' ? 'Buy Now' : (e.status || 'View')
      }));

      renderCarouselSection(soonContainer, soon, 'No upcoming events in this category.', (e) => ({
        layout: 'home',
        variant: 'soon',
        ctaText: e.status === 'Coming Soon' ? 'Soon' : (e.status || 'View'),
        preferPoster: true
      }));
    } catch (err) {
      if (seq !== requestSeq) return;
      console.error('Failed to filter events:', err);
      const msg = '<p class="empty-events-msg">Unable to load events. Please try again.</p>';
      if (popularContainer) popularContainer.innerHTML = msg;
      if (soonContainer) soonContainer.innerHTML = msg;
    }
  }

  try {
    const [res, categoryRes] = await Promise.all([
      API.events.list(),
      API.categories.list()
    ]);
    const allEvents = (res && res.events) || [];
    renderFeaturedHero(allEvents);
    populateFilterOptions(allEvents, (categoryRes && categoryRes.categories) || []);
    await filterAndRenderEvents();
  } catch (err) {
    console.error('Failed to load events:', err);
  }

  searchInput.addEventListener('input', () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(filterAndRenderEvents, 250);
  });

  [categoryFilter, statusFilter, provinceFilter, monthFilter, sortFilter].forEach((el) => {
    if (el) el.addEventListener('change', () => filterAndRenderEvents());
  });

  if (resetFilters) {
    resetFilters.addEventListener('click', () => {
      searchInput.value = '';
      [categoryFilter, statusFilter, provinceFilter, monthFilter, sortFilter].forEach((el) => {
        if (el) el.value = '';
      });
      filterAndRenderEvents();
    });
  }

  const navSearchTrigger = document.getElementById('navSearchTrigger');
  if (navSearchTrigger && searchInput) {
    navSearchTrigger.addEventListener('click', () => {
      searchInput.focus();
      searchInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
  }

  document.querySelectorAll('.carousel-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const container = document.getElementById(btn.dataset.target);
      if (container) {
        const firstCard = container.querySelector('.card-home, .card-popular, .card-soon');
        const step = firstCard ? firstCard.offsetWidth + 24 : 444;
        container.scrollBy({
          left: btn.dataset.direction === 'left' ? -step : step,
          behavior: 'smooth'
        });
      }
    });
  });
});

/**
 * TicketHub - My Tickets & Purchase History Controller (public/js/my-tickets.js)
 * Implements UI-12 (Oat Milk e-ticket viewer), real QR code display (qrDataUrl),
 * red ◀ ▶ seat carousel navigation, interactive ticket selector grid (FR-28, FR-29),
 * purchase & booking history table (FR-32), and cancellation/refund modal (FR-38, FR-39).
 */

document.addEventListener('DOMContentLoaded', async () => {
  const urlParams = new URLSearchParams(window.location.search);
  let targetBookingId = urlParams.get('bookingId') || '';
  let targetTicketCode = urlParams.get('ticketCode') || '';

  const ticketCarouselArea = document.getElementById('ticketCarouselArea');
  const emptyTicketsState = document.getElementById('emptyTicketsState');
  const activeTicketViewer = document.getElementById('activeTicketViewer');
  const ticketIndexBadge = document.getElementById('ticketIndexBadge');
  const prevTicketBtn = document.getElementById('prevTicketBtn');
  const nextTicketBtn = document.getElementById('nextTicketBtn');
  const myTicketsGridSection = document.getElementById('myTicketsGridSection');
  const myTicketsCountEl = document.getElementById('myTicketsCount');
  const myTicketsGrid = document.getElementById('myTicketsGrid');
  const purchaseHistoryBody = document.getElementById('purchaseHistoryBody');

  // Active E-Ticket Card Elements
  const ticketEventTitle = document.getElementById('ticketEventTitle');
  const ticketRound = document.getElementById('ticketRound');
  const ticketSeat = document.getElementById('ticketSeat');
  const ticketHolder = document.getElementById('ticketHolder');
  const ticketVenue = document.getElementById('ticketVenue');
  const ticketQrImage = document.getElementById('ticketQrImage');
  const ticketCode = document.getElementById('ticketCode');
  const ticketStatusBadge = document.getElementById('ticketStatusBadge');

  let ticketsList = [];
  let currentTicketIdx = 0;
  let historyList = [];

  function escapeSafe(val) {
    if (window.Popup && typeof window.Popup.escapeHtml === 'function') {
      return window.Popup.escapeHtml(val);
    }
    return String(val ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function promptForLogin() {
    Auth.openAuthModal(async () => {
      await loadData();
    });
  }

  async function loadData() {
    if (!Auth.isLoggedIn() && !API.getToken()) {
      promptForLogin();
      return;
    }

    try {
      // 1. Load user's electronic tickets (FR-28, FR-29)
      const tRes = await API.tickets.getMyTickets();
      ticketsList = (tRes && tRes.tickets) || [];

      if (targetTicketCode) {
        const idx = ticketsList.findIndex(
          (t) => String(t.ticketCode || '').toUpperCase() === targetTicketCode.toUpperCase()
        );
        if (idx !== -1) currentTicketIdx = idx;
        targetTicketCode = '';
      } else if (targetBookingId) {
        const idx = ticketsList.findIndex((t) => t.bookingId === targetBookingId);
        if (idx !== -1) currentTicketIdx = idx;
        targetBookingId = '';
      } else if (currentTicketIdx >= ticketsList.length) {
        currentTicketIdx = 0;
      }

      renderTicketCarousel();
      renderTicketsGrid();

      // 2. Load purchase & booking history (FR-32)
      const hRes = await API.tickets.getHistory();
      historyList = (hRes && hRes.history) || [];
      renderPurchaseHistory();
    } catch (err) {
      if (err.status === 401) {
        Auth.currentUser = null;
        API.setToken('');
        Auth.renderNavbarAuth();
        promptForLogin();
        return;
      }
      console.error('Failed to load tickets/history:', err);
    }
  }

  function getStatusBadgeClass(status) {
    if (status === 'CHECKED_IN') return 'badge-pill-blue fs-075';
    if (status === 'CANCELLED') return 'badge-pill-cancelled';
    return 'badge-pill-red fs-075';
  }

  function renderTicketCarousel() {
    if (!ticketCarouselArea) return;

    if (ticketsList.length === 0) {
      if (emptyTicketsState) {
        emptyTicketsState.classList.remove('d-none');
        emptyTicketsState.hidden = false;
      }
      if (activeTicketViewer) {
        activeTicketViewer.classList.add('d-none');
        activeTicketViewer.hidden = true;
      }
      return;
    }

    if (emptyTicketsState) {
      emptyTicketsState.classList.add('d-none');
      emptyTicketsState.hidden = true;
    }
    if (activeTicketViewer) {
      activeTicketViewer.classList.remove('d-none');
      activeTicketViewer.hidden = false;
    }

    const t = ticketsList[currentTicketIdx] || ticketsList[0];

    if (ticketIndexBadge) {
      ticketIndexBadge.textContent = `Ticket ${currentTicketIdx + 1} of ${ticketsList.length}`;
    }

    if (ticketEventTitle) ticketEventTitle.textContent = t.eventTitle || 'Live Event';
    if (ticketRound) {
      ticketRound.innerHTML = `<i class="fa-solid fa-calendar-days mr-4" aria-hidden="true"></i> ${escapeSafe(t.roundLabel || 'Show Round')}`;
    }
    if (ticketSeat) ticketSeat.textContent = `Seat ${t.seatNumber} (${t.zoneName || 'Standard'})`;
    if (ticketHolder) {
      ticketHolder.textContent = t.holderName || (Auth.currentUser && Auth.currentUser.name) || 'Ticket Holder';
    }
    if (ticketVenue) {
      ticketVenue.textContent = t.venue || 'Main Venue';
    }
    if (ticketCode) ticketCode.textContent = t.ticketCode;

    if (ticketQrImage) {
      ticketQrImage.src =
        t.qrDataUrl ||
        `https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(t.ticketCode)}`;
      ticketQrImage.alt = `QR Code for ${t.ticketCode}`;
    }

    if (ticketStatusBadge) {
      ticketStatusBadge.textContent = t.status;
      ticketStatusBadge.className = getStatusBadgeClass(t.status);
    }

    if (prevTicketBtn) prevTicketBtn.disabled = currentTicketIdx === 0;
    if (nextTicketBtn) nextTicketBtn.disabled = currentTicketIdx === ticketsList.length - 1;
  }

  function renderTicketsGrid() {
    if (myTicketsCountEl) {
      myTicketsCountEl.textContent = String(ticketsList.length);
    }
    if (!myTicketsGrid) return;

    if (ticketsList.length === 0) {
      if (myTicketsGridSection) {
        myTicketsGridSection.classList.add('d-none');
        myTicketsGridSection.hidden = true;
      }
      myTicketsGrid.innerHTML = '';
      return;
    }

    if (myTicketsGridSection) {
      myTicketsGridSection.classList.remove('d-none');
      myTicketsGridSection.hidden = false;
    }

    myTicketsGrid.innerHTML = ticketsList
      .map((t, idx) => {
        const isActive = idx === currentTicketIdx;
        const badgeCls = getStatusBadgeClass(t.status);
        const holder = t.holderName || (Auth.currentUser && Auth.currentUser.name) || 'Ticket Holder';
        return `
          <button type="button" class="my-ticket-mini-card ${isActive ? 'active' : ''}" data-ticket-idx="${idx}" aria-pressed="${isActive ? 'true' : 'false'}">
            <div class="my-ticket-mini-header">
              <span class="my-ticket-mini-code">${escapeSafe(t.ticketCode)}</span>
              <span class="${badgeCls}">${escapeSafe(t.status)}</span>
            </div>
            <div class="my-ticket-mini-title">${escapeSafe(t.eventTitle || 'Live Event')}</div>
            <div class="my-ticket-mini-meta"><i class="fa-solid fa-calendar-days mr-4" aria-hidden="true"></i>${escapeSafe(t.roundLabel || 'Show Round')}</div>
            <div class="my-ticket-mini-seat"><i class="fa-solid fa-chair mr-4" aria-hidden="true"></i>${escapeSafe(t.zoneName || 'Zone')} • Seat ${escapeSafe(t.seatNumber)}</div>
            <div class="my-ticket-mini-meta"><i class="fa-solid fa-user mr-4" aria-hidden="true"></i>${escapeSafe(holder)}</div>
          </button>
        `;
      })
      .join('');

    myTicketsGrid.querySelectorAll('.my-ticket-mini-card').forEach((cardBtn) => {
      cardBtn.addEventListener('click', () => {
        const idx = Number(cardBtn.dataset.ticketIdx);
        if (!Number.isNaN(idx) && idx >= 0 && idx < ticketsList.length) {
          currentTicketIdx = idx;
          renderTicketCarousel();
          renderTicketsGrid();
          if (ticketCarouselArea && typeof ticketCarouselArea.scrollIntoView === 'function') {
            ticketCarouselArea.scrollIntoView({ behavior: 'smooth', block: 'center' });
          }
        }
      });
    });
  }

  if (prevTicketBtn) {
    prevTicketBtn.addEventListener('click', () => {
      if (currentTicketIdx > 0) {
        currentTicketIdx--;
        renderTicketCarousel();
        renderTicketsGrid();
      }
    });
  }

  if (nextTicketBtn) {
    nextTicketBtn.addEventListener('click', () => {
      if (currentTicketIdx < ticketsList.length - 1) {
        currentTicketIdx++;
        renderTicketCarousel();
        renderTicketsGrid();
      }
    });
  }

  function getBookingStatusBadgeClass(status) {
    if (status === 'PAID') return 'history-status-badge history-status-badge--paid';
    if (status === 'PENDING') return 'history-status-badge history-status-badge--pending';
    if (status === 'CANCELLED') return 'history-status-badge history-status-badge--cancelled';
    return 'history-status-badge history-status-badge--expired';
  }

  function renderPurchaseHistory() {
    if (!purchaseHistoryBody) return;

    if (historyList.length === 0) {
      purchaseHistoryBody.innerHTML = `
        <tr>
          <td colspan="7" class="tc c-muted p-24">
            No purchase history available.
          </td>
        </tr>
      `;
      return;
    }

    purchaseHistoryBody.innerHTML = historyList
      .map((b) => {
        const dateStr = b.createdAt ? new Date(b.createdAt).toLocaleDateString() : '—';
        const hasCheckedInTicket = Array.isArray(b.tickets) && b.tickets.some((t) => t.status === 'CHECKED_IN');
        const canCancel = b.status === 'PAID' && b.allowCancellation !== false && !hasCheckedInTicket;
        const canViewTicket = b.status === 'PAID' && ticketsList.some((t) => t.bookingId === b.id);
        const canPayPending = b.status === 'PENDING';
        const statusBadgeCls = getBookingStatusBadgeClass(b.status);
        const eventName = b.eventTitle || 'Live Event';
        const seatsDisplay = Array.isArray(b.seatNumbers) && b.seatNumbers.length > 0
          ? b.seatNumbers.join(', ')
          : '—';

        const actionButtons = [];
        if (canViewTicket) {
          actionButtons.push(
            `<button type="button" class="btn-view-booking-ticket btn-pill-blue btn-history-action" data-id="${escapeSafe(b.id)}">View QR</button>`
          );
        }
        if (canPayPending) {
          actionButtons.push(
            `<a href="/checkout?bookingId=${encodeURIComponent(b.id)}" class="btn-pill-red btn-history-action">Pay Now</a>`
          );
        }
        if (canCancel) {
          actionButtons.push(
            `<button type="button" class="btn-cancel-booking btn-pill-outline" data-id="${escapeSafe(b.id)}">Cancel &amp; Refund</button>`
          );
        }

        return `
          <tr>
            <td><strong>${escapeSafe(b.id)}</strong></td>
            <td>${escapeSafe(dateStr)}</td>
            <td>
              <strong>${escapeSafe(eventName)}</strong>
              ${b.roundLabel ? `<div class="fs-08 c-muted">${escapeSafe(b.roundLabel)}</div>` : ''}
            </td>
            <td>
              ${b.zoneName ? `<span class="fs-08 c-muted block">${escapeSafe(b.zoneName)}</span>` : ''}
              <strong>${escapeSafe(seatsDisplay)}</strong>
            </td>
            <td><strong>${Number(b.totalAmount || 0).toLocaleString()} THB</strong></td>
            <td>
              <span class="${statusBadgeCls}">
                ${escapeSafe(b.status)}
              </span>
            </td>
            <td>
              ${
                actionButtons.length > 0
                  ? `<div class="history-actions-cell">${actionButtons.join('')}</div>`
                  : '<span class="c-muted fs-085">—</span>'
              }
            </td>
          </tr>
        `;
      })
      .join('');

    purchaseHistoryBody.querySelectorAll('.btn-view-booking-ticket').forEach((btn) => {
      btn.addEventListener('click', () => {
        const bookingId = btn.dataset.id;
        const idx = ticketsList.findIndex((t) => t.bookingId === bookingId);
        if (idx !== -1) {
          currentTicketIdx = idx;
          renderTicketCarousel();
          renderTicketsGrid();
          if (ticketCarouselArea && typeof ticketCarouselArea.scrollIntoView === 'function') {
            ticketCarouselArea.scrollIntoView({ behavior: 'smooth', block: 'center' });
          }
        }
      });
    });

    purchaseHistoryBody.querySelectorAll('.btn-cancel-booking').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.id;
        const booking = historyList.find((x) => x.id === id);
        if (booking) openRefundModal(booking);
      });
    });
  }

  function openRefundModal(booking) {
    const refundableAmount = Math.max(0, (booking.subtotal || 0) - (booking.discountAmount || 0));
    const nonRefundableFee = booking.serviceFee || ((booking.seatIds || []).length * 40);
    const titleId = `refund-dialog-title-${Math.random().toString(36).slice(2, 8)}`;

    const dialog = document.createElement('dialog');
    dialog.className = 'th-popup-dialog';
    dialog.setAttribute('closedby', 'any');
    dialog.setAttribute('aria-labelledby', titleId);

    dialog.innerHTML = `
      <div class="th-popup th-popup--big refund-modal-dialog">
        <div class="th-popup-header refund-modal-header">
          <h3 class="th-popup-title refund-modal-title" id="${titleId}">Cancel Booking &amp; Refund</h3>
          <button type="button" class="modal-close-btn th-popup-close" title="Close" aria-label="Close">
            <img src="/images/popup-close-icon.svg" alt="Close" class="refund-modal-close-img">
          </button>
        </div>
        <div class="modal-body refund-modal-body">
          <p class="refund-modal-lead">
            Are you sure you want to cancel your booking for <strong>${escapeSafe(booking.eventTitle || 'Live Event')}</strong>?
          </p>
          <div class="refund-breakdown-box">
            <div class="refund-breakdown-row">
              <span>Ticket Subtotal:</span>
              <strong>${Number(booking.subtotal || 0).toLocaleString()} THB</strong>
            </div>
            ${
              booking.discountAmount > 0
                ? `<div class="refund-breakdown-row refund-breakdown-row--discount">
                    <span>Discounts:</span>
                    <strong>-${Number(booking.discountAmount).toLocaleString()} THB</strong>
                  </div>`
                : ''
            }
            <div class="refund-breakdown-row refund-breakdown-row--fee">
              <span>Service Fee (Non-refundable):</span>
              <strong>${Number(nonRefundableFee).toLocaleString()} THB</strong>
            </div>
            <div class="refund-breakdown-divider"></div>
            <div class="refund-breakdown-total">
              <span>Total Refund Amount:</span>
              <span>${Number(refundableAmount).toLocaleString()} THB</span>
            </div>
          </div>
          <p class="refund-policy-note">
            * Refund policy (FR-38, FR-39): The subtotal minus discounts will be refunded to your original payment method. The 40 THB/seat service fee is non-refundable. Your reserved seats will immediately return to available status.
          </p>
        </div>
        <div class="th-popup-actions--big refund-modal-actions">
          <button type="button" class="btn-confirm-refund th-popup-btn th-popup-btn--primary th-popup-btn--destructive">Confirm Refund</button>
          <button type="button" class="btn-cancel-close th-popup-btn th-popup-btn--secondary" autofocus>Keep Booking</button>
        </div>
      </div>
    `;

    document.body.appendChild(dialog);

    const closeModal = () => {
      if (dialog.open && typeof dialog.close === 'function') dialog.close();
      dialog.remove();
    };

    dialog.addEventListener('close', () => {
      dialog.remove();
    }, { once: true });

    if (!('closedBy' in HTMLDialogElement.prototype)) {
      const outside = (e) => {
        const r = dialog.getBoundingClientRect();
        return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
      };
      let pressedOutside = false;
      dialog.addEventListener('pointerdown', (e) => {
        pressedOutside = (e.target === dialog) && outside(e);
      });
      dialog.addEventListener('pointerup', (e) => {
        if (pressedOutside && (e.target === dialog) && outside(e)) closeModal();
      });
    }

    dialog.querySelector('.modal-close-btn').onclick = closeModal;
    dialog.querySelector('.btn-cancel-close').onclick = closeModal;

    dialog.querySelector('.btn-confirm-refund').onclick = async () => {
      const confirmBtn = dialog.querySelector('.btn-confirm-refund');
      if (confirmBtn && confirmBtn.disabled) return;
      if (confirmBtn) {
        confirmBtn.disabled = true;
        confirmBtn.textContent = 'Processing...';
      }
      try {
        const res = await API.booking.cancel(booking.id);
        closeModal();
        await Popup.alert(
          `Booking cancelled successfully. Refund of ${res.refundableAmount.toLocaleString()} THB issued.`,
          { title: 'Refund Processed' }
        );
        await loadData();
      } catch (err) {
        if (confirmBtn) {
          confirmBtn.disabled = false;
          confirmBtn.textContent = 'Confirm Refund';
        }
        await Popup.alert(err.message || 'Failed to cancel booking.', { title: 'Cancellation Error' });
      }
    };

    if (typeof dialog.showModal === 'function') {
      dialog.showModal();
    } else {
      dialog.setAttribute('open', '');
    }
  }

  await Auth.ready;
  await loadData();
});

/**
 * TicketHub - In-App Notifications Controller (Vanilla JS)
 * Polls user notifications, manages the bell badge count, and renders the dropdown drawer.
 */

const Notifications = {
  items: [],
  pollInterval: null,

  async init() {
    this.bindEvents();
    if (window.Auth && Auth.ready) {
      await Auth.ready;
    }
    if (Auth.isLoggedIn()) {
      await this.fetch();
      this.startPolling();
    }
    Auth.onAuthChange((user) => {
      if (user) {
        this.fetch();
        this.startPolling();
      } else {
        this.stopPolling();
        this.items = [];
        this.updateBadge(0);
      }
    });
  },

  startPolling() {
    this.stopPolling();
    this.pollInterval = setInterval(() => {
      if (Auth.isLoggedIn()) {
        this.fetch();
      }
    }, 15000); // Poll every 15s
  },

  stopPolling() {
    if (this.pollInterval) {
      clearInterval(this.pollInterval);
      this.pollInterval = null;
    }
  },

  async fetch() {
    try {
      const res = await API.admin.getNotifications();
      this.items = (res && res.notifications) || [];
      const unreadCount = this.items.filter((n) => !n.isRead).length;
      this.updateBadge(unreadCount);
      return this.items;
    } catch (_) {
      // User might be unauthenticated
      return [];
    }
  },

  updateBadge(count) {
    const badge = document.querySelector('.notification-badge');
    if (!badge) return;
    if (count > 0) {
      badge.textContent = count > 99 ? '99+' : count;
      badge.classList.remove('d-none');
      badge.hidden = false;
    } else {
      badge.classList.add('d-none');
      badge.hidden = true;
    }
  },

  bindEvents() {
    const bellBtn = document.querySelector('.notification-bell-btn');
    if (!bellBtn) return;

    bellBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!Auth.isLoggedIn()) {
        Auth.openAuthModal();
        return;
      }
      this.toggleDropdown(bellBtn);
    });
  },

  toggleDropdown(anchor) {
    let dropdown = document.getElementById('notificationDropdownDrawer');
    if (dropdown) {
      dropdown.remove();
      return;
    }

    dropdown = document.createElement('div');
    dropdown.id = 'notificationDropdownDrawer';
    dropdown.className = 'notification-dropdown';

    const unreadCount = this.items.filter((n) => !n.isRead).length;

    let itemsHtml = '';
    if (this.items.length === 0) {
      itemsHtml = `
        <li class="tc p-24 c-muted fs-09">
          No notifications yet.
        </li>
      `;
    } else {
      itemsHtml = this.items
        .map((n) => {
          const dateStr = new Date(n.createdAt).toLocaleString();
          return `
            <li class="notification-item ${n.isRead ? '' : 'unread'}" data-id="${escapeHtml(n.id)}">
              <div class="flex between items-start mb-4">
                <strong class="fs-09 c-ink">${escapeHtml(n.subject || 'Notification')}</strong>
                <span class="fs-075 c-faint">${escapeHtml(dateStr)}</span>
              </div>
              <p class="fs-085 c-ink-2 mb-6 lh-14">${escapeHtml(n.message || '')}</p>
              ${
                !n.isRead
                  ? `<button class="btn-mark-read border-none bg-white c-blue fs-075 fw-7 cursor-pointer p-0" data-id="${escapeHtml(n.id)}">Mark as read</button>`
                  : ''
              }
            </li>
          `;
        })
        .join('');
    }

    dropdown.innerHTML = `
      <div class="notification-dropdown-header">
        <span>Notifications (${unreadCount} unread)</span>
      </div>
      <ul class="notification-dropdown-list">
        ${itemsHtml}
      </ul>
    `;

    document.body.appendChild(dropdown);

    // Close on click outside
    const closeHandler = (e) => {
      if (!dropdown.contains(e.target) && e.target !== anchor && !anchor.contains(e.target)) {
        dropdown.remove();
        document.removeEventListener('click', closeHandler);
      }
    };
    setTimeout(() => document.addEventListener('click', closeHandler), 10);

    // Bind mark-read buttons
    dropdown.querySelectorAll('.btn-mark-read').forEach((btn) => {
      btn.addEventListener('click', async (e) => {
        e.stopPropagation();
        const id = btn.dataset.id;
        try {
          await API.admin.markNotificationRead(id);
          const item = this.items.find((x) => x.id === id);
          if (item) item.isRead = true;
          const li = btn.closest('.notification-item');
          if (li) li.classList.remove('unread');
          btn.remove();
          const newUnread = this.items.filter((x) => !x.isRead).length;
          this.updateBadge(newUnread);
          const countSpan = dropdown.querySelector('.notification-dropdown-header span');
          if (countSpan) countSpan.textContent = `Notifications (${newUnread} unread)`;
        } catch (err) {
          console.error('Failed to mark read', err);
        }
      });
    });
  }
};

window.Notifications = Notifications;
document.addEventListener('DOMContentLoaded', () => Notifications.init());

