    if (req.file) {
      avatarUrl = `/uploads/${req.file.filename}`;
    } else if (req.body && (req.body.avatarUrl !== undefined || req.body.avatarDataUrl !== undefined || req.body.avatar !== undefined)) {
      const candidate = req.body.avatarUrl !== undefined
