    }
  }

  // 4. Rounds validation
  if (!isUpdate || payload.rounds !== undefined) {
    if (!Array.isArray(payload.rounds) || payload.rounds.length === 0) {
      return { valid: false, error: 'At least one round is required.' };
    }
