const { PaymentModel } = require('../models');

const VALID_METHODS = ['PROMPTPAY', 'CREDIT_CARD', 'DEBIT_CARD', 'KBANK', 'KRUNGTHAI', 'TRUEMONEY'];

function gatewayError(message, status = 400) {
  const err = new Error(message);
  err.status = status;
  return err;
}

/**
 * Validates method-specific gateway details (when supplied) and records payment.
 */
function processPayment({ bookingId, userId, method, amount, paymentDetails }) {
  if (!VALID_METHODS.includes(method)) {
    throw gatewayError(`Invalid payment method. Allowed: ${VALID_METHODS.join(', ')}`);
  }

  if (paymentDetails && typeof paymentDetails === 'object') {
    if (paymentDetails.simulateFailure === true) {
      throw gatewayError('Payment declined by gateway simulator.');
    }

    if (method === 'CREDIT_CARD' || method === 'DEBIT_CARD') {
      if (paymentDetails.cardNumber !== undefined) {
        const digits = typeof paymentDetails.cardNumber === 'string'
          ? paymentDetails.cardNumber.replace(/\s+/g, '')
          : '';
        if (!/^\d{13,19}$/.test(digits)) {
          throw gatewayError('Invalid card number. Enter 13 to 19 digits.');
        }
      }

      if (paymentDetails.expiry !== undefined) {
        const expiry = typeof paymentDetails.expiry === 'string' ? paymentDetails.expiry.trim() : '';
        if (!/^(0[1-9]|1[0-2])\/\d{2}$/.test(expiry)) {
          throw gatewayError('Invalid card expiry date. Use MM/YY format.');
        }
      }

      if (paymentDetails.cvv !== undefined) {
        const cvv = typeof paymentDetails.cvv === 'string' ? paymentDetails.cvv.trim() : '';
        if (!/^\d{3,4}$/.test(cvv)) {
          throw gatewayError('Invalid security code (CVV). Enter 3 or 4 digits.');
        }
      }

      if (paymentDetails.cardHolder !== undefined) {
        const holder = typeof paymentDetails.cardHolder === 'string' ? paymentDetails.cardHolder.trim() : '';
        if (!holder) {
          throw gatewayError('Cardholder name is required.');
        }
      }
    } else if (method === 'KBANK' || method === 'KRUNGTHAI' || method === 'TRUEMONEY') {
      if (paymentDetails.phone !== undefined) {
        const cleaned = typeof paymentDetails.phone === 'string'
          ? paymentDetails.phone.replace(/[\s-]+/g, '')
          : '';
        if (!/^\d{9,13}$/.test(cleaned)) {
          throw gatewayError('Invalid registered phone or citizen ID.');
        }
      }
    }
  }

  return PaymentModel.create({
    bookingId,
    userId,
    method,
    amount
  });
}

module.exports = {
  VALID_METHODS,
  processPayment
};

/**
 * Social login token verification (Google & Facebook).
 *
 * The browser obtains a token from the provider; the backend NEVER trusts profile data sent by the
 * client. It verifies the token with the provider and uses only the identity returned by that check.
 *
 * Environment variables:
 *   GOOGLE_CLIENT_ID      OAuth 2.0 Web client ID (Google Cloud Console)
 *   FACEBOOK_APP_ID       Facebook App ID
 *   FACEBOOK_APP_SECRET   Facebook App Secret (server-side only, never sent to the browser)
 *
 * Requires Node 18+ (global fetch).
 */

const GOOGLE_TOKENINFO_URL = 'https://oauth2.googleapis.com/tokeninfo';
const GOOGLE_ISSUERS = ['accounts.google.com', 'https://accounts.google.com'];
const FACEBOOK_GRAPH_URL = 'https://graph.facebook.com/v27.0';
const REQUEST_TIMEOUT_MS = 8000;

class SocialAuthError extends Error {
  constructor(message, status = 401) {
    super(message);
    this.name = 'SocialAuthError';
    this.status = status;
  }
}

function env(name) {
  return String(process.env[name] || '').trim();
}

/** Simulated phone OTP login is a demo feature: disabled in production unless explicitly enabled. */
function isPhoneDemoEnabled() {
  return process.env.NODE_ENV !== 'production' || env('ALLOW_SIMULATED_PHONE_LOGIN') === 'true';
}

/** Public, non-secret settings the browser needs to start the provider login flow. */
function getPublicConfig() {
  const googleClientId = env('GOOGLE_CLIENT_ID');
  const facebookAppId = env('FACEBOOK_APP_ID');
  const facebookConfigured = Boolean(facebookAppId && env('FACEBOOK_APP_SECRET'));
  return {
    google: { enabled: Boolean(googleClientId), clientId: googleClientId || null },
    facebook: { enabled: facebookConfigured, appId: facebookConfigured ? facebookAppId : null },
    phoneDemo: isPhoneDemoEnabled()
  };
}

async function fetchJson(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const res = await fetch(url, { signal: controller.signal });
    const data = await res.json().catch(() => ({}));
    return { ok: res.ok, data: data || {} };
  } catch (_err) {
    throw new SocialAuthError('Could not reach the login provider. Please try again.', 502);
  } finally {
    clearTimeout(timer);
  }
}

function safeAvatar(url) {
  return typeof url === 'string' && /^https:\/\//i.test(url) ? url : '';
}

/** Verifies a Google ID token (the "credential" returned by Google Identity Services). */
async function verifyGoogleIdToken(idToken) {
  const clientId = env('GOOGLE_CLIENT_ID');
  if (!clientId) throw new SocialAuthError('Google login is not configured on this server.', 503);

  const { ok, data } = await fetchJson(`${GOOGLE_TOKENINFO_URL}?id_token=${encodeURIComponent(idToken)}`);
  if (!ok || !data.sub) throw new SocialAuthError('Invalid Google token.');
  if (data.aud !== clientId) throw new SocialAuthError('Google token was not issued for this application.');
  if (!GOOGLE_ISSUERS.includes(data.iss)) throw new SocialAuthError('Invalid Google token issuer.');
  if (!(Number(data.exp) * 1000 > Date.now())) throw new SocialAuthError('Google token has expired.');

  return {
    provider: 'gmail',
    providerId: String(data.sub),
    email: data.email ? String(data.email).trim().toLowerCase() : null,
    emailVerified: data.email_verified === true || data.email_verified === 'true',
    name: data.name ? String(data.name).trim() : '',
    avatarUrl: safeAvatar(data.picture)
  };
}

/** Verifies a Facebook user access token and loads the profile with it. */
async function verifyFacebookAccessToken(accessToken) {
  const appId = env('FACEBOOK_APP_ID');
  const appSecret = env('FACEBOOK_APP_SECRET');
  if (!appId || !appSecret) throw new SocialAuthError('Facebook login is not configured on this server.', 503);

  const appToken = `${appId}|${appSecret}`;
  const debug = await fetchJson(
    `${FACEBOOK_GRAPH_URL}/debug_token?input_token=${encodeURIComponent(accessToken)}&access_token=${encodeURIComponent(appToken)}`
  );
  const info = debug.data && debug.data.data;
  if (!debug.ok || !info || info.is_valid !== true) throw new SocialAuthError('Invalid Facebook token.');
  if (String(info.app_id) !== appId) throw new SocialAuthError('Facebook token was not issued for this application.');
  if (info.expires_at && Number(info.expires_at) * 1000 < Date.now()) {
    throw new SocialAuthError('Facebook token has expired.');
  }

  const me = await fetchJson(
    `${FACEBOOK_GRAPH_URL}/me?fields=id,name,email,picture.type(large)&access_token=${encodeURIComponent(accessToken)}`
  );
  if (!me.ok || !me.data.id) throw new SocialAuthError('Could not read the Facebook profile.');
  if (info.user_id && String(info.user_id) !== String(me.data.id)) {
    throw new SocialAuthError('Facebook token does not match the profile.');
  }

  const email = me.data.email ? String(me.data.email).trim().toLowerCase() : null;
  const picture = me.data.picture && me.data.picture.data ? me.data.picture.data.url : '';
  return {
    provider: 'facebook',
    providerId: String(me.data.id),
    email,
    // Facebook only returns an email address it has confirmed.
    emailVerified: Boolean(email),
    name: me.data.name ? String(me.data.name).trim() : '',
    avatarUrl: safeAvatar(picture)
  };
}

/** provider: 'gmail' | 'facebook'. Resolves to { provider, providerId, email, emailVerified, name, avatarUrl }. */
async function verifyProviderToken(provider, token) {
  if (provider === 'gmail') return verifyGoogleIdToken(token);
  if (provider === 'facebook') return verifyFacebookAccessToken(token);
  throw new SocialAuthError('Unsupported provider.', 400);
}

module.exports = {
  SocialAuthError,
  getPublicConfig,
  isPhoneDemoEnabled,
  verifyGoogleIdToken,
  verifyFacebookAccessToken,
  verifyProviderToken
};

const fs = require('fs');
const path = require('path');

const DATA_DIR = path.join(__dirname, '..', '..', 'data');
const BACKUP_DIR = path.join(DATA_DIR, 'backups');

const COLLECTIONS = [
  'users',
  'events',
  'categories',
  'seats',
  'bookings',
  'payments',
  'tickets',
  'promotions',
  'notifications',
  'support'
];

class JsonStore {
  constructor() {
    this.cache = {};
    this.ensureDirs();
  }

  ensureDirs() {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    if (!fs.existsSync(BACKUP_DIR)) {
      fs.mkdirSync(BACKUP_DIR, { recursive: true });
    }
  }

  filePath(collection) {
    return path.join(DATA_DIR, `${collection}.json`);
  }

  init(seedGenerator) {
    this.ensureDirs();
    const usersPath = this.filePath('users');
    if (!fs.existsSync(usersPath)) {
      const initialData = seedGenerator();
      for (const col of COLLECTIONS) {
        this.cache[col] = initialData[col] || [];
        this.save(col);
      }
    } else {
      const categoriesPath = this.filePath('categories');
      const seedCategories = !fs.existsSync(categoriesPath)
        ? (seedGenerator().categories || [])
        : null;
      for (const col of COLLECTIONS) {
        if (col === 'categories' && seedCategories) {
          this.cache[col] = seedCategories;
          this.save(col);
        } else {
          this.load(col);
        }
      }
    }
  }

  resetWithSeed(seedGenerator) {
    const initialData = seedGenerator();
    for (const col of COLLECTIONS) {
      this.cache[col] = initialData[col] || [];
      this.save(col);
    }
    return this.cache;
  }

  load(collection) {
    const fp = this.filePath(collection);
    if (!fs.existsSync(fp)) {
      this.cache[collection] = [];
      this.save(collection);
      return [];
    }
    try {
      const raw = fs.readFileSync(fp, 'utf8');
      this.cache[collection] = JSON.parse(raw);
    } catch (err) {
      console.error(`Error loading ${collection}.json:`, err.message);
      this.cache[collection] = [];
    }
    return this.cache[collection];
  }

  save(collection) {
    this.ensureDirs();
    const fp = this.filePath(collection);
    const tmpPath = `${fp}.tmp`;
    const data = JSON.stringify(this.cache[collection] || [], null, 2);
    try {
      fs.writeFileSync(tmpPath, data, 'utf8');
      fs.renameSync(tmpPath, fp);
    } catch (_) {
      try {
        fs.writeFileSync(fp, data, 'utf8');
      } catch (__) {
        // retry once on Windows transient EPERM/EBUSY
        try {
          fs.writeFileSync(fp, data, 'utf8');
        } catch (___) {
          // ignore transient lock in test
        }
      }
      if (fs.existsSync(tmpPath)) {
        try {
          fs.unlinkSync(tmpPath);
        } catch (__) {
          // ignore cleanup error
        }
      }
    }
  }

  getAll(collection) {
    if (!this.cache[collection]) {
      this.load(collection);
    }
    return this.cache[collection];
  }

  findById(collection, id) {
    return this.getAll(collection).find((item) => item.id === id) || null;
  }

  find(collection, predicate) {
    return this.getAll(collection).filter(predicate);
  }

  findOne(collection, predicate) {
    return this.getAll(collection).find(predicate) || null;
  }

  insert(collection, item) {
    const list = this.getAll(collection);
    list.push(item);
    this.save(collection);
    return item;
  }

  insertMany(collection, items) {
    const list = this.getAll(collection);
    list.push(...items);
    this.save(collection);
    return items;
  }

  update(collection, id, updates) {
    const list = this.getAll(collection);
    const idx = list.findIndex((item) => item.id === id);
    if (idx === -1) return null;
    list[idx] = { ...list[idx], ...updates };
    this.save(collection);
    return list[idx];
  }

  remove(collection, id) {
    const list = this.getAll(collection);
    const idx = list.findIndex((item) => item.id === id);
    if (idx === -1) return false;
    list.splice(idx, 1);
    this.save(collection);
    return true;
  }

  removeWhere(collection, predicate) {
    const list = this.getAll(collection);
    const next = list.filter((item) => !predicate(item));
    const removedCount = list.length - next.length;
    this.cache[collection] = next;
    if (removedCount > 0) {
      this.save(collection);
    }
    return removedCount;
  }

  /**
   * Releases any seat holds whose 10-minute timer has expired
   * and marks PENDING bookings as EXPIRED (FR-23 / Background Scheduler)
   */
  expireHeldSeats() {
    const now = Date.now();
    const seats = this.getAll('seats');
    let seatsChanged = false;

    for (const seat of seats) {
      if (seat.status === 'HELD' && seat.holdExpiresAt && new Date(seat.holdExpiresAt).getTime() <= now) {
        seat.status = 'AVAILABLE';
        seat.heldByUserId = null;
        seat.holdExpiresAt = null;
        seat.bookingId = null;
        seatsChanged = true;
      }
    }
    if (seatsChanged) {
      this.save('seats');
    }

    const bookings = this.getAll('bookings');
    let bookingsChanged = false;
    for (const booking of bookings) {
      if (booking.status === 'PENDING' && booking.holdExpiresAt && new Date(booking.holdExpiresAt).getTime() <= now) {
        booking.status = 'EXPIRED';
        bookingsChanged = true;
      }
    }
    if (bookingsChanged) {
      this.save('bookings');
    }

    return { seatsChanged, bookingsChanged };
  }

  /**
   * Creates a snapshot backup of all JSON collections (NFR-11)
   */
  createBackup(label = 'manual') {
    this.ensureDirs();
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const backupId = `backup-${label}-${timestamp}.json`;
    const snapshot = {
      backupId,
      createdAt: new Date().toISOString(),
      collections: {}
    };
    for (const col of COLLECTIONS) {
      snapshot.collections[col] = this.getAll(col);
    }
    const backupPath = path.join(BACKUP_DIR, backupId);
    fs.writeFileSync(backupPath, JSON.stringify(snapshot, null, 2), 'utf8');
    return {
      backupId,
      createdAt: snapshot.createdAt,
      counts: Object.fromEntries(COLLECTIONS.map((c) => [c, snapshot.collections[c].length]))
    };
  }

  listBackups() {
    this.ensureDirs();
    const files = fs.readdirSync(BACKUP_DIR).filter((f) => f.endsWith('.json'));
    return files
      .map((f) => {
        const stat = fs.statSync(path.join(BACKUP_DIR, f));
        return {
          backupId: f,
          sizeBytes: stat.size,
          createdAt: stat.mtime.toISOString()
        };
      })
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }

  /**
   * Restores collections from a backup snapshot (NFR-12)
   */
  restoreBackup(backupId) {
    const targetFile = backupId
      ? path.join(BACKUP_DIR, path.basename(backupId))
      : (() => {
          const list = this.listBackups();
          return list.length > 0 ? path.join(BACKUP_DIR, list[0].backupId) : null;
        })();

    if (!targetFile || !fs.existsSync(targetFile)) {
      throw new Error('Backup file not found');
    }
    const raw = JSON.parse(fs.readFileSync(targetFile, 'utf8'));
    if (!raw.collections) {
      throw new Error('Invalid backup format');
    }
    for (const col of COLLECTIONS) {
      if (Array.isArray(raw.collections[col])) {
        this.cache[col] = raw.collections[col];
        this.save(col);
      }
    }
    return {
      restoredFrom: path.basename(targetFile),
      restoredAt: new Date().toISOString()
    };
  }
}

